INSERT INTO jingo_checkout_bundles(id,code,access_hash,total,data) VALUES (?,?,?,?,?)',[$in['requestId'],$code,hash('sha256',$in['accessKey']),$state['total'],self::json($data)]);foreach($refs as $kind=>$entity)$this->query('INSERT INTO jingo_checkout_members(kind,entity_id,bundle_id) VALUES (?,?,?)',[$kind,$entity,$in['requestId']]);$this->audit('customer','checkout.create',$in['requestId']);return ['code'=>$code,'total'=>$state['total'],'method'=>$in['method'],'codes'=>$codes]+(isset($in['tickets'])?['ticketAccessKey'=>$in['tickets']['accessKey']]:[]);});
