    private function created(array $row,array $d,array $in):array{return ['code'=>$row['code'],'total'=>(int)$row['total'],'method'=>$d['method'],'codes'=>$d['codes']]+(isset($in['tickets'])?['ticketAccessKey'=>$in['tickets']['accessKey']]:[]);}
    public function lookup(array $in):array
