    }
    public function list():array{return $this->tx(function(){$out=[];foreach($this->query('SELECT code,total,status,data,created_at FROM jingo_checkout_bundles ORDER BY created_at DESC,id DESC LIMIT 100')->fetchAll(PDO::FETCH_ASSOC) as $r){$d=json_decode($r['data'],true,512,JSON_THROW_ON_ERROR);$r['total']=(int)$r['total'];$r['data']=array_intersect_key($d,array_flip(['contact','codes','method','reference','paidMethod','manual']));$out[]=$r;}return ['data'=>$out];},true);}
    public function gatewayState(string $id):array
    {
        if(!$this->db->inTransaction())throw new LogicException('Gateway state requires transaction.');$row=$this->query('SELECT * FROM jingo_checkout_bundles WHERE id=? FOR UPDATE',[$id])->fetch(PDO::FETCH_ASSOC);if(!$row)throw new HttpError(404,'Không tìm thấy mã tổng.');if($row['status']!=='PENDING')throw new HttpError(409,'Mã tổng đã thu tiền hoặc không còn chờ thu.');$data=json_decode($row['data'],true,512,JSON_THROW_ON_ERROR);$rows=$this->loadRefs($data['refs']);$state=$this->state($data['refs'],$rows);$amounts=$data['amounts'];ksort($amounts);if($state['total']!==(int)$row['total']||$state['amounts']!==$amounts)throw new HttpError(409,'Giá thành phần đã thay đổi.');foreach($data['refs'] as $kind=>$entity)if($this->query('SELECT bundle_id FROM jingo_checkout_members WHERE kind=? AND entity_id=?',[$kind,$entity])->fetchColumn()!==$id)throw new HttpError(409,'Thành phần không khớp.');return $rows+['bundle'=>$row,'total'=>$state['total']];
