'#'.$o['code'],'note'=>'Thanh toán chung '.$code],$actor,null,true);if($nested){$ids=array_column($rows['orders'],'id');foreach($ids as $id)$this->query("UPDATE jingo_order_payments SET method='VNPAY' WHERE order_id=? AND reference_hash=?",[$id,hash('sha256',$reference.'#'.$this->query('SELECT code FROM jingo_orders WHERE id=?',[$id])->fetchColumn())]);}if($rows['cart']){$this->query('UPDATE jingo_carts SET version=version+1 WHERE id=?',[$rows['cart']['id']]);OrderMail::enqueue($this->db,$rows['orders'][0]['id'],'CART_PAY',(int)$rows['orders'][0]['version']+1);}foreach(['ride'=>'jingo_ride_bookings','gift'=>'jingo_gift_orders'] as $kind=>$table)if($rows[$kind]){$row=$rows[$kind];$data=json_decode($row['data'],true,512,JSON_THROW_ON_ERROR);$data=array_replace($data,['paymentStatus'=>'PAID','paidAmount'=>$data['total'],'paidAt'=>gmdate('Y-m-d\TH:i:s\Z'),'paymentReference'=>$reference,'bundleCode'=>$code]);$this->query('UPDATE '.$table.' SET data=?'.($kind==='ride'?',version=version+1':'').' WHERE id=?',[self::json($data),$row['id']]);$this->audit($actor,$kind.'.pay',$row['id']);}$d=array_replace($d,['paidAt'=>gmdate('Y-m-d\TH:i:s\Z'),'reference'=>$reference,'paidMethod'=>$method]);$this->query("UPDATE jingo_checkout_bundles SET status='PAID',data=? WHERE id=?",[self::json($d),$r['id']]);$this->audit($actor,'checkout.collect',$r['id']);return ['ok'=>true];},false,$nested);
